export default function MedusaNavbar() {
  const [activeMenu, setActiveMenu] = useState<"product" | "resources" | null>(
    null
  );
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const handleMouseEnter = (menu: "product" | "resources") => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setActiveMenu(menu);
  };

  const handleMouseLeave = () => {
    timeoutRef.current = setTimeout(() => {
      setActiveMenu(null);
    }, 120);
  };

  const currentContent =
    activeMenu === "product"
      ? PRODUCT_MENU
      : activeMenu === "resources"
        ? RESOURCES_MENU
        : null;

  return (
    <div
      className="w-full bg-white text-neutral-900 font-sans selection:bg-neutral-200 antialiased relative min-h-screen"
      onMouseLeave={handleMouseLeave}
    >
      {/* Top Header Bar */}
      <header className="sticky top-0 z-50 w-full bg-white border-b border-[#E5E7EB]/80">
        <div className="max-w-[1240px] mx-auto px-6 h-[56px] flex items-center justify-between">
          {/* Left Navigation Cluster */}
          <div className="flex items-center">
