              href="#"
              className="mr-7 flex items-center gap-2 focus:outline-none"
              aria-label="Medusa home"
            >
              <MedusaGlyphIcon />
            </a>

            {/* Nav Links */}
            <nav className="flex items-center space-x-[22px]">
              {/* Product Trigger */}
              <button
                type="button"
                onMouseEnter={() => handleMouseEnter("product")}
                onClick={() =>
                  setActiveMenu(activeMenu === "product" ? null : "product")
                }
                className={`flex items-center gap-1.5 text-[13.5px] font-[450] tracking-[-0.01em] transition-colors py-2 focus:outline-none ${
                  activeMenu === "product"
                    ? "text-black font-medium"
                    : "text-neutral-700 hover:text-black"
                }`}
              >
                <span>Product</span>
                <ChevronDownIcon isOpen={activeMenu === "product"} />
              </button>

              {/* Resources Trigger */}
              <button
                type="button"
                onMouseEnter={() => handleMouseEnter("resources")}
                onClick={() =>
                  setActiveMenu(activeMenu === "resources" ? null : "resources")
                }
                className={`flex items-center gap-1.5 text-[13.5px] font-[450] tracking-[-0.01em] transition-colors py-2 focus:outline-none ${
                  activeMenu === "resources"
                    ? "text-black font-medium"
                    : "text-neutral-700 hover:text-black"
                }`}
              >
                <span>Resources</span>
                <ChevronDownIcon isOpen={activeMenu === "resources"} />
              </button>

              <a
                href="#enterprise"
                onMouseEnter={() => setActiveMenu(null)}
                className="text-[13.5px] font-[450] tracking-[-0.01em] text-neutral-700 hover:text-black transition-colors py-2"
              >
                Enterprise
              </a>

              <a
                href="#pricing"
                onMouseEnter={() => setActiveMenu(null)}
                className="text-[13.5px] font-[450] tracking-[-0.01em] text-neutral-700 hover:text-black transition-colors py-2"
              >
                Pricing
              </a>

              <a
                href="#documentation"
                onMouseEnter={() => setActiveMenu(null)}
                className="text-[13.5px] font-[450] tracking-[-0.01em] text-neutral-700 hover:text-black transition-colors py-2"
              >
                Documentation
              </a>
            </nav>
          </div>

          {/* Right Action Cluster */}
          <div className="flex items-center space-x-3.5">
            {/* GitHub Stars Pill */}
            <a
              href="https://github.com/medusajs/medusa"
              target="_blank"
              rel="noreferrer"
              className="flex items-center gap-1.5 px-2.5 py-1 text-[13px] font-[450] text-neutral-800 border border-neutral-200/90 rounded-full hover:bg-neutral-50 hover:border-neutral-300 transition-all shadow-[0_1px_2px_rgba(0,0,0,0.02)]"
            >
              <GitHubIcon />
              <span className="tabular-nums">37.1k</span>
            </a>

            {/* View Demo Button */}
            <a
              href="#demo"
              className="px-3 py-1.5 text-[13px] font-medium text-neutral-800 hover:text-black hover:bg-neutral-100/70 rounded-md transition-colors"
            >
              View demo
            </a>

            {/* Start for Free CTA */}
            <a
              href="#start"
              className="px-3.5 py-1.5 text-[13px] font-medium text-white bg-black hover:bg-neutral-800 active:bg-neutral-900 rounded-md transition-all shadow-[0_1px_2px_rgba(0,0,0,0.06)]"
            >
              Start for free
            </a>
          </div>
        </div>

        {/* Mega Menu Dropdown Panel */}
        <AnimatePresence>
          {activeMenu && currentContent && (
            <motion.div
              key={activeMenu}
              initial={{ opacity: 0, y: -4 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -4 }}
              transition={{ duration: 0.16, ease: [0.16, 1, 0.3, 1] }}
              onMouseEnter={() => {
                if (timeoutRef.current) clearTimeout(timeoutRef.current);
              }}
              onMouseLeave={handleMouseLeave}
              className="absolute top-[56px] left-0 w-full bg-white border-b border-[#E5E7EB] shadow-[0_14px_34px_-6px_rgba(0,0,0,0.05)] z-40"
            >
              <div className="max-w-[1240px] mx-auto px-6 pt-7 pb-9">
                <div className="grid grid-cols-4 gap-x-12">
                  {/* Columns Section */}
                  {currentContent.columns.map((col, idx) => (
                    <div key={idx} className="flex flex-col">
                      <h4 className="text-[13.5px] font-semibold text-neutral-900 tracking-[-0.01em]">
                        {col.heading}
                      </h4>
                      <p className="text-[12.5px] leading-[1.38] text-neutral-500 font-normal mt-1 mb-5">
                        {col.description}
                      </p>
                      <ul className="flex flex-col space-y-[9px]">
                        {col.links.map((link, linkIdx) => (
                          <li key={linkIdx}>
                            <a
                              href={link.href}
                              className="text-[13px] text-neutral-600 hover:text-neutral-950 transition-colors duration-150 block font-normal leading-normal"
                            >
                              {link.title}
                            </a>
                          </li>
                        ))}
                      </ul>
                    </div>
                  ))}

                  {/* Optional 4th Column Featured Card (Resources tab) */}
                  {currentContent.type === "columns-with-card" &&
                    currentContent.featuredCard && (
                      <div className="flex flex-col pl-2">
                        <a
                          href={currentContent.featuredCard.href}
                          className="group block overflow-hidden rounded-lg border border-neutral-200/90 bg-neutral-50/50 hover:border-neutral-300 transition-all p-3.5"
                        >
                          {/* Realistic Mock Visual for 'Medusa Security' */}
                          <div className="w-full h-[106px] bg-gradient-to-br from-[#1E293B] via-[#0F172A] to-[#020617] rounded-md p-3 relative flex flex-col justify-between overflow-hidden shadow-inner border border-neutral-800/40">
                            <div className="flex items-center justify-between">
                              <span className="text-[10px] font-mono tracking-wider text-neutral-400 uppercase">
                                Secured
                              </span>
                              <span className="h-2 w-2 rounded-full bg-emerald-400 ring-4 ring-emerald-500/20" />
                            </div>
                            <div>
                              <div className="text-[14px] font-semibold text-white tracking-tight flex items-center gap-1.5">
                                <span className="inline-block w-2.5 h-2.5 rounded-full bg-blue-500" />
                                Medusa Security
                              </div>
                              <div className="text-[10px] text-neutral-400 font-mono mt-0.5">
                                v2.0 · Guard Architecture
                              </div>
                            </div>
                          </div>

                          {/* Card Meta & Title */}
                          <div className="mt-3">
                            <span className="text-[11.5px] font-medium text-neutral-400">
                              {currentContent.featuredCard.category}
                            </span>
                            <p className="text-[13px] font-medium text-neutral-900 group-hover:text-black leading-snug mt-0.5">
                              {currentContent.featuredCard.title}
                            </p>
                          </div>
                        </a>
                      </div>
                    )}
                </div>
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </header>

      {/* Hero Section Grounding */}
      <main className="max-w-[1240px] mx-auto px-6 pt-24 pb-32">
        <h1 className="text-4xl md:text-[64px] font-semibold tracking-[-0.035em] text-black leading-[1.08] max-w-[820px]">
          Build and operate your commerce stack with agents
        </h1>
      </main>
    </div>
  );
}

